// C header
int format_message(const char* name, char* out, size_t out_size);

// Minimal C impl (header + body)
#include <string.h>
#include <errno.h>
int format_message(const char* name, char* out, size_t out_size){
  const char* greet = "Hello, ";
  size_t needed = strlen(greet) + strlen(name) + 2; // including '!'
  if (out_size <= needed) { errno = ERANGE; return -1; }
  strcpy(out, greet);
  strcat(out, name);
  strcat(out, "!");
  return (int)strlen(out);
}
