package main
/*
#include <stdlib.h>
#include "format.h"
*/
import "C"
import (
  "errors"
  "unsafe"
)

func FormatMessage(name string) (string, error) {
  sizes := []int{128, 256, 512, 1024}
  for _, s := range sizes {
    buf := make([]byte, s)
    cname := C.CString(name)
    defer C.free(unsafe.Pointer(cname))
    n := C.format_message(cname, (*C.char)(unsafe.Pointer(&buf[0])), C.size_t(s))
    if n >= 0 {
      return string(buf[:n]), nil
    }
    if C.errno != C.ERANGE {
      return "", errors.New("format failed")
    }
  }
  return "", errors.New("buffer too small")
}
